tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import { readdirSync, readFileSync } from \"node:fs\";
for (const file of readdirSync(\"visits\").filter(file => file.endsWith(\".json\"))) {
  const result = JSON.parse(readFileSync(\"visits/\" + file));
  console.log(file, result.error, result.timeline.length);
  for (const [i, {action, state}] of result.timeline.entries()) {
    console.log(i, state.width, action.op, action.target ?? \"\", state.page.split(\"\\n\").slice(2).join(\" | \"));
  }
}
NODE"

